// jot - a terminal-focused note management tool.
//
// This is a from-scratch reimplementation using only the Rust
// standard library.  The behaviour has been reconstructed from the
// compiled reference binary by observation.

mod cli;
mod config;
mod error;
mod fsutil;
mod help;
mod state;
mod toml_lite;
mod tree;

mod commands;

use std::env;
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let program = args.get(0).cloned().unwrap_or_else(|| "executable".into());
    // Only the last path component is used by clap for help output.
    let prog = program
        .rsplit('/')
        .next()
        .unwrap_or("executable")
        .to_string();

    match cli::parse(&prog, &args[1..]) {
        cli::ParseResult::Exec(cmd) => match commands::run(&prog, cmd) {
            Ok(()) => ExitCode::from(0),
            Err(e) => {
                e.print();
                ExitCode::from(0)
            }
        },
        cli::ParseResult::Help(text) => {
            print!("{}", text);
            ExitCode::from(0)
        }
        cli::ParseResult::Error(text) => {
            eprint!("{}", text);
            ExitCode::from(2)
        }
    }
}
EOF
