//! Runtime error reporting.  Errors are sent to stderr with a red
//! "error:" prefix.  The process exits with status 0 after printing
//! them, matching the reference binary.

use std::fmt;

pub const RED: &str = "\x1b[0;31m";
pub const BLUE: &str = "\x1b[0;34m";
pub const RESET: &str = "\x1b[0m";

pub struct AppError {
    pub msg: String,
    /// When true, the message is prepended with the red "error:"
    /// prefix.  Some rare error paths in the reference binary emit a
    /// plain message followed by a coloured error; composite errors
    /// can be constructed with `AppError::composite`.
    pub with_prefix: bool,
}

impl AppError {
    pub fn new<S: Into<String>>(msg: S) -> Self {
        AppError { msg: msg.into(), with_prefix: true }
    }

    /// Build a composite error that emits `prefix` verbatim and then
    /// the standard red-prefixed error line for `msg`.
    pub fn composite<S: Into<String>, T: Into<String>>(prefix: S, msg: T) -> Self {
        let mut s = String::new();
        s.push_str(&prefix.into());
        s.push_str(RED);
        s.push_str("error");
        s.push_str(RESET);
        s.push_str(": ");
        s.push_str(&msg.into());
        s.push('\n');
        AppError { msg: s, with_prefix: false }
    }

    pub fn print(&self) {
        if self.with_prefix {
            eprintln!("{}error{}: {}", RED, RESET, self.msg);
        } else {
            eprint!("{}", self.msg);
        }
    }
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.with_prefix {
            write!(f, "{}error{}: {}", RED, RESET, self.msg)
        } else {
            write!(f, "{}", self.msg)
        }
    }
}

impl From<std::io::Error> for AppError {
    fn from(e: std::io::Error) -> AppError {
        // The reference binary uses lower-case "undefined error" for
        // some uncategorised io failures (notably `xdg-open`).  For
        // generic conversions we fall back to a readable message.
        AppError::new(format!("io error: {}", e))
    }
}
EOF
