        self.sections.iter().find(|(n, _)| n == name).map(|(_, v)| v)
    }

    pub fn section_mut(&mut self, name: &str) -> &mut Vec<(String, Value)> {
        if let Some(idx) = self.sections.iter().position(|(n, _)| n == name) {
            return &mut self.sections[idx].1;
        }
        self.sections.push((name.to_string(), Vec::new()));
        &mut self.sections.last_mut().unwrap().1
    }

    pub fn section_map(&self, name: &str) -> BTreeMap<String, String> {
        let mut out = BTreeMap::new();
        if let Some(items) = self.section(name) {
            for (k, v) in items {
                if let Value::Str(s) = v {
                    out.insert(k.clone(), s.clone());
                }
            }
        }
        out
    }

    pub fn serialize(&self) -> String {
        let mut out = String::new();
        for (k, v) in &self.top {
            out.push_str(k);
            out.push_str(" = ");
            write_value(&mut out, v);
            out.push('\n');
        }
        for (name, items) in &self.sections {
            if !out.is_empty() && !out.ends_with("\n\n") {
                out.push('\n');
            }
            out.push('[');
            out.push_str(name);
            out.push_str("]\n");
            for (k, v) in items {
                out.push_str(k);
                out.push_str(" = ");
                write_value(&mut out, v);
                out.push('\n');
            }
        }
        out
    }
}

fn write_value(out: &mut String, value: &Value) {
    match value {
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Str(s) => write_string(out, s),
        Value::List(items) => {
            out.push('[');
            let mut first = true;
            for v in items {
                if !first { out.push_str(", "); }
                first = false;
                write_value(out, v);
            }
            out.push(']');
        }
    }
}

fn write_string(out: &mut String, s: &str) {
    // TOML literal strings use single quotes and don't support any
    // escapes.  If the value contains a single quote or newline,
    // fall back to the multi-line literal form which can hold any
    // content that does not include three consecutive single quotes.
    if s.contains('\'') || s.contains('\n') {
        out.push_str("'''");
        // Leading newline makes reading friendlier; TOML strips the
        // first \n after an opening '''.
        if s.contains('\n') {
            out.push('\n');
        }
        out.push_str(s);
        out.push_str("'''");
    } else {
        out.push('\'');
        out.push_str(s);
        out.push('\'');
    }
}

/// Parse a minimal TOML document.  The parser is intentionally
/// tolerant: we only need to read files our own writer produces, or
/// user-tweaked versions of the same.
pub fn parse(text: &str) -> TomlDoc {
    let mut doc = TomlDoc::new();
    let bytes = text.as_bytes();
    let mut i = 0;
    let mut current_section: Option<String> = None;
    while i < bytes.len() {
        // Skip whitespace & newlines
        while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\r' | b'\n') {
            i += 1;
        }
        if i >= bytes.len() { break; }
        if bytes[i] == b'#' {
            while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
            continue;
        }
        if bytes[i] == b'[' {
            i += 1;
            let start = i;
            while i < bytes.len() && bytes[i] != b']' { i += 1; }
            let name: String = text[start..i].trim().to_string();
            current_section = Some(name);
            if i < bytes.len() { i += 1; } // skip ]
            // consume rest of line
            while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
            continue;
        }

        // Parse key
        let key_start = i;
        while i < bytes.len() && bytes[i] != b'=' && bytes[i] != b'\n' { i += 1; }
        let key: String = text[key_start..i].trim().to_string();
        if i >= bytes.len() || bytes[i] != b'=' {
            // malformed - skip rest of line
            while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
            continue;
        }
        i += 1; // skip =
        // skip horizontal whitespace
        while i < bytes.len() && matches!(bytes[i], b' ' | b'\t') { i += 1; }
        let value = parse_value(text, &mut i);

        if let Some(section) = &current_section {
            // update or insert
            let items = doc.section_mut(section);
            if let Some(slot) = items.iter_mut().find(|(k, _)| k == &key) {
                slot.1 = value;
            } else {
                items.push((key, value));
            }
        } else {
            doc.set(key, value);
        }

        // consume trailing newline
        while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
    }
    doc
}

fn parse_value(text: &str, i: &mut usize) -> Value {
    let bytes = text.as_bytes();
    if *i >= bytes.len() { return Value::Str(String::new()); }
    match bytes[*i] {
        b'\'' => parse_lit_str(text, i),
        b'"' => parse_basic_str(text, i),
        b'[' => parse_array(text, i),
        b't' | b'f' => parse_bool(text, i),
        _ => {
            // fall-through: unquoted value, read until newline.
            let start = *i;
            while *i < bytes.len() && bytes[*i] != b'\n' { *i += 1; }
            Value::Str(text[start..*i].trim().to_string())
        }
    }
}

fn parse_lit_str(text: &str, i: &mut usize) -> Value {
    let bytes = text.as_bytes();
    // multi-line?
    if bytes.len() >= *i + 3 && &bytes[*i..*i + 3] == b"'''" {
        *i += 3;
        // Skip a single leading newline immediately after opening '''
        if *i < bytes.len() && bytes[*i] == b'\r' { *i += 1; }
        if *i < bytes.len() && bytes[*i] == b'\n' { *i += 1; }
        let start = *i;
        while *i + 3 <= bytes.len() && &bytes[*i..*i + 3] != b"'''" { *i += 1; }
        let s = text[start..*i].to_string();
        if *i + 3 <= bytes.len() { *i += 3; }
        return Value::Str(s);
    }
    *i += 1; // skip opening quote
    let start = *i;
    while *i < bytes.len() && bytes[*i] != b'\'' && bytes[*i] != b'\n' { *i += 1; }
    let s = text[start..*i].to_string();
    if *i < bytes.len() && bytes[*i] == b'\'' { *i += 1; }
    Value::Str(s)
}

fn parse_basic_str(text: &str, i: &mut usize) -> Value {
    let bytes = text.as_bytes();
    *i += 1;
    let mut s = String::new();
    while *i < bytes.len() && bytes[*i] != b'"' {
        if bytes[*i] == b'\\' && *i + 1 < bytes.len() {
            let nxt = bytes[*i + 1];
            s.push(match nxt {
                b'n' => '\n',
                b't' => '\t',
                b'r' => '\r',
                b'\\' => '\\',
                b'"' => '"',
                b'\'' => '\'',
                _ => nxt as char,
            });
            *i += 2;
        } else {
            let c = bytes[*i] as char;
            s.push(c);
            *i += 1;
        }
    }
    if *i < bytes.len() && bytes[*i] == b'"' { *i += 1; }
    Value::Str(s)
}

fn parse_array(text: &str, i: &mut usize) -> Value {
    let bytes = text.as_bytes();
    *i += 1; // skip [
    let mut items: Vec<Value> = Vec::new();
    loop {
        while *i < bytes.len() && matches!(bytes[*i], b' ' | b'\t' | b'\n' | b'\r' | b',') {
            *i += 1;
        }
        if *i >= bytes.len() || bytes[*i] == b']' { break; }
        let v = parse_value(text, i);
        items.push(v);
    }
    if *i < bytes.len() && bytes[*i] == b']' { *i += 1; }
    Value::List(items)
}

fn parse_bool(text: &str, i: &mut usize) -> Value {
    let bytes = text.as_bytes();
    if bytes.len() >= *i + 4 && &bytes[*i..*i + 4] == b"true" {
        *i += 4;
        Value::Bool(true)
    } else if bytes.len() >= *i + 5 && &bytes[*i..*i + 5] == b"false" {
        *i += 5;
        Value::Bool(false)
    } else {
        let start = *i;
        while *i < bytes.len() && bytes[*i] != b'\n' { *i += 1; }
        Value::Str(text[start..*i].trim().to_string())
    }
}
