//! Persistent state: user config, the vault registry and per-vault
//! data files.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use crate::error::AppError;
use crate::toml_lite::{self, TomlDoc, Value};

pub fn config_dir() -> PathBuf {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        if !xdg.is_empty() {
            return PathBuf::from(xdg).join("jot");
        }
    }
    let home = std::env::var("HOME").unwrap_or_else(|_| "/".into());
    PathBuf::from(home).join(".config").join("jot")
}

pub fn data_dir() -> PathBuf {
    if let Ok(xdg) = std::env::var("XDG_DATA_HOME") {
        if !xdg.is_empty() {
            return PathBuf::from(xdg).join("jot");
        }
    }
    let home = std::env::var("HOME").unwrap_or_else(|_| "/".into());
    PathBuf::from(home).join(".local").join("share").join("jot")
}

pub fn config_path() -> PathBuf { config_dir().join("config") }
pub fn vaults_path() -> PathBuf { data_dir().join("vaults") }

fn ensure_dir(p: &Path) -> std::io::Result<()> {
    if !p.exists() {
        fs::create_dir_all(p)?;
    }
    Ok(())
}

// ---------------------------------------------------------------- //
// User configuration ($XDG_CONFIG_HOME/jot/config)                  //
// ---------------------------------------------------------------- //

pub struct Config {
    pub doc: TomlDoc,
}

impl Config {
    pub fn load() -> Self {
        let path = config_path();
        if !path.exists() {
            let mut doc = TomlDoc::new();
            doc.set("editor", Value::Str("nvim".into()));
            doc.set("conflict", Value::Bool(true));
            let cfg = Config { doc };
            cfg.save();
            return cfg;
        }
        let contents = fs::read_to_string(&path).unwrap_or_default();
        let doc = toml_lite::parse(&contents);
        Config { doc }
    }

    pub fn save(&self) {
        let _ = ensure_dir(&config_dir());
        let _ = fs::write(config_path(), self.doc.serialize());
    }

    pub fn editor(&self) -> String {
        self.doc
            .get("editor")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string()
    }

    pub fn conflict(&self) -> bool {
        self.doc
            .get("conflict")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
    }
}

// ---------------------------------------------------------------- //
// Vault registry ($XDG_DATA_HOME/jot/vaults)                        //
// ---------------------------------------------------------------- //

pub struct Vaults {
    pub doc: TomlDoc,
}

impl Vaults {
    pub fn load() -> Self {
        let path = vaults_path();
        if !path.exists() {
            let mut doc = TomlDoc::new();
            // Always write a [vaults] section even when empty
            doc.section_mut("vaults");
            let v = Vaults { doc };
            v.save();
            return v;
        }
        let contents = fs::read_to_string(&path).unwrap_or_default();
        let mut doc = toml_lite::parse(&contents);
        // Make sure the [vaults] table is present when we re-save.
        if doc.section("vaults").is_none() {
            doc.section_mut("vaults");
        }
        Vaults { doc }
    }

    pub fn save(&self) {
        let _ = ensure_dir(&data_dir());
        let _ = fs::write(vaults_path(), self.doc.serialize());
    }

    pub fn current(&self) -> Option<String> {
        self.doc
            .get("current")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
    }

    pub fn set_current(&mut self, name: Option<&str>) {
        if let Some(n) = name {
            self.doc.set("current", Value::Str(n.into()));
        } else {
            self.doc.remove("current");
        }
    }

    pub fn list(&self) -> Vec<(String, String)> {
        if let Some(items) = self.doc.section("vaults") {
            items
                .iter()
                .filter_map(|(k, v)| v.as_str().map(|s| (k.clone(), s.to_string())))
                .collect()
        } else {
            Vec::new()
        }
    }

    pub fn as_map(&self) -> BTreeMap<String, String> {
        self.doc.section_map("vaults")
    }

    pub fn contains(&self, name: &str) -> bool {
        self.list().iter().any(|(n, _)| n == name)
    }

    pub fn location_of(&self, name: &str) -> Option<String> {
        self.list().into_iter().find(|(n, _)| n == name).map(|(_, l)| l)
    }

    pub fn add(&mut self, name: &str, location: &str) {
        let items = self.doc.section_mut("vaults");
        if let Some(slot) = items.iter_mut().find(|(k, _)| k == name) {
            slot.1 = Value::Str(location.to_string());
        } else {
            items.push((name.to_string(), Value::Str(location.to_string())));
        }
    }

    pub fn remove(&mut self, name: &str) {
        let items = self.doc.section_mut("vaults");
        items.retain(|(k, _)| k != name);
    }

    pub fn rename(&mut self, old: &str, new: &str) {
        let items = self.doc.section_mut("vaults");
        for (k, _) in items.iter_mut() {
            if k == old {
                *k = new.to_string();
            }
        }
    }
}

// ---------------------------------------------------------------- //
// Per-vault data (<vault>/.jot/data)                                //
// ---------------------------------------------------------------- //

#[derive(Debug)]
pub struct VaultData {
    pub name: String,
    pub location: String,
    pub folder: String,
    pub history: Vec<String>,
}

impl VaultData {
    pub fn new(name: &str, location: &str) -> Self {
        VaultData {
            name: name.into(),
            location: location.into(),
            folder: String::new(),
            history: Vec::new(),
        }
    }

    pub fn path_for(location: &str, name: &str) -> PathBuf {
        Path::new(location).join(name).join(".jot").join("data")
    }

    pub fn load(location: &str, name: &str) -> Result<Self, AppError> {
        let path = Self::path_for(location, name);
        let contents = fs::read_to_string(&path)
            .map_err(|e| AppError::new(format!("no such file or directory (os error {})", e.raw_os_error().unwrap_or(2))))?;
        let doc = toml_lite::parse(&contents);
        let name = doc.get("name").and_then(|v| v.as_str()).unwrap_or(name).to_string();
        let location = doc.get("location").and_then(|v| v.as_str()).unwrap_or(location).to_string();
        let folder = doc.get("folder").and_then(|v| v.as_str()).unwrap_or("").to_string();
        let history = if let Some(Value::List(items)) = doc.get("history") {
            items.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect()
        } else {
            Vec::new()
        };
        Ok(VaultData { name, location, folder, history })
    }

    pub fn save(&self) -> std::io::Result<()> {
        let mut doc = TomlDoc::new();
        doc.set("name", Value::Str(self.name.clone()));
        doc.set("location", Value::Str(self.location.clone()));
        doc.set("folder", Value::Str(self.folder.clone()));
        doc.set(
            "history",
            Value::List(self.history.iter().map(|s| Value::Str(s.clone())).collect()),
        );
        let path = Self::path_for(&self.location, &self.name);
        if let Some(parent) = path.parent() {
            ensure_dir(parent)?;
        }
        fs::write(&path, doc.serialize())
    }

    pub fn vault_root(&self) -> PathBuf {
        Path::new(&self.location).join(&self.name)
    }

    pub fn current_path(&self) -> PathBuf {
        if self.folder.is_empty() {
            self.vault_root()
        } else {
            self.vault_root().join(&self.folder)
        }
    }
}
