//! Filesystem helpers shared across commands.

use std::fs;
use std::path::{Component, Path, PathBuf};

use crate::error::AppError;

/// Characters that are rejected in user-supplied note/folder/vault
/// names (matching the reference implementation).
pub fn name_is_invalid(name: &str) -> bool {
    name.chars().any(|c| matches!(c, '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|'))
}

pub fn note_filename(name: &str) -> String {
    // The reference binary replaces the (single) last extension with
    // ".md" when present and simply appends ".md" otherwise.
    let p = Path::new(name);
    if p.extension().is_some() {
        let mut pb = PathBuf::from(name);
        pb.set_extension("md");
        pb.to_string_lossy().into_owned()
    } else {
        format!("{}.md", name)
    }
}

pub fn display_note_name(filename: &str) -> String {
    let p = Path::new(filename);
    if p.extension().map(|e| e == "md").unwrap_or(false) {
        p.file_stem()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_else(|| filename.to_string())
    } else {
        filename.to_string()
    }
}

/// Check if `target` exists (file or directory) underneath `dir`.
pub fn entry_exists(dir: &Path, name: &str) -> bool {
    dir.join(name).exists()
}

/// Normalise a relative path composed of name components and `..`
/// elements without touching the filesystem.  `base` is the current
/// in-vault folder (as a `/` separated string).  Returns the new
/// folder path on success or an error string when the path escapes
/// the vault.
pub fn resolve_folder_path(base: &str, input: &str) -> Result<String, AppError> {
    // Reject absolute paths
    if input.starts_with('/') {
        return Err(AppError::new("couldn't find the path specified"));
    }
    // Start with the components of `base`
    let mut parts: Vec<String> = if base.is_empty() {
        Vec::new()
    } else {
        base.split('/').map(|s| s.to_string()).collect()
    };
    let p = Path::new(input);
    for c in p.components() {
        match c {
            Component::CurDir => { /* skip */ }
            Component::ParentDir => {
                if parts.pop().is_none() {
                    return Err(AppError::new("path crosses the bounds of vault"));
                }
            }
            Component::Normal(s) => {
                let s = s.to_string_lossy().to_string();
                if !s.is_empty() {
                    parts.push(s);
                }
            }
            Component::RootDir | Component::Prefix(_) => {
                return Err(AppError::new("couldn't find the path specified"));
            }
        }
    }
    Ok(parts.join("/"))
}

/// Recursively copy `from` to `to`.  `to` itself should not yet
/// exist.  `rename` is preferred when both paths live on the same
/// filesystem; this helper is a fallback.
pub fn copy_recursive(from: &Path, to: &Path) -> std::io::Result<()> {
    let md = fs::metadata(from)?;
    if md.is_dir() {
        fs::create_dir_all(to)?;
        for entry in fs::read_dir(from)? {
            let e = entry?;
            let from_sub = e.path();
            let to_sub = to.join(e.file_name());
            copy_recursive(&from_sub, &to_sub)?;
        }
    } else {
        fs::copy(from, to)?;
    }
    Ok(())
}

pub fn move_item(from: &Path, to: &Path) -> std::io::Result<()> {
    match fs::rename(from, to) {
        Ok(()) => Ok(()),
        Err(_) => {
            copy_recursive(from, to)?;
            let md = fs::metadata(from)?;
            if md.is_dir() {
                fs::remove_dir_all(from)?;
            } else {
                fs::remove_file(from)?;
            }
            Ok(())
        }
    }
}
