//! Help text rendering.  The main help has a custom layout; the
//! per-subcommand pages follow a compact clap-v3 style.

const BLUE: &str = "\x1b[0;34m";
const RESET: &str = "\x1b[0m";

/// The banner-and-command-list shown when the program is invoked
/// with no arguments, `help`, `-h` or `--help`.
pub fn main_help() -> String {
    let mut s = String::new();
    s.push_str(BLUE);
    s.push_str("________      _____ \n");
    s.push_str("______(_)_______  /_\n");
    s.push_str("_____  /_  __ \\  __/\n");
    s.push_str("____  / / /_/ / /_  \n");
    s.push_str("___  /  \\____/\\__/  \n");
