    s.push_str(&line("open", Some("op"), "open a note from current folder", 4));
    s.push_str(&line("opdir", Some("od"), "open current folder in file explorer", 4));
    s.push_str(&line("chdir", Some("cd"), "change folder within current vault", 4));
    s.push_str(&line("list", Some("ls"), "list items in current folder", 4));
    s.push_str("\nperform fs operations on items\n");
    s.push_str(&line("remove", Some("rm"), "remove an item ", 4));
    s.push_str(&line("rename", Some("rn"), "rename an item ", 4));
    s.push_str(&line("move", Some("mv"), "move an item to a new location", 4));
    s.push_str(&line("vmove", Some("vm"), "move an item to a different vault", 4));
    s.push_str("\nconfig\n");
    s.push_str(&line("config", Some("cf"), "display, set or open config", 4));
