fn write_wrapped(s: &mut String, text: &str, first_col: usize) {
    // Break text into lines of up to 91 - first_col characters,
    // breaking on word boundaries, indenting continuation lines by
    // `first_col` spaces.
    let wrap = 91 - first_col;
    let words: Vec<&str> = text.split_whitespace().collect();
    let mut line = String::new();
    let mut first = true;
    for w in words {
        if !first && line.len() + 1 + w.len() > wrap {
            s.push_str(&line);
            s.push('\n');
            for _ in 0..first_col { s.push(' '); }
            line.clear();
            first = true;
        }
        if !first { line.push(' '); }
        line.push_str(w);
        first = false;
    }
    if !line.is_empty() { s.push_str(&line); }
