    for w in words {
        if !first && line.len() + 1 + w.len() > wrap {
            s.push_str(&line);
            s.push('\n');
            for _ in 0..first_col { s.push(' '); }
            line.clear();
            first = true;
        }
        if !first { line.push(' '); }
        line.push_str(w);
        first = false;
    }
    if !line.is_empty() { s.push_str(&line); }
}

fn clap_help(prog: &str, sub: &str, about: &str, usage: &[String],
             args: &[(&str, &str)], opts: &[(&str, &str)]) -> String {
    let mut s = String::new();
    s.push_str(prog);
    s.push('-');
    s.push_str(sub);
    s.push_str(" \n");
    s.push_str(about);
    s.push_str("\n\nUSAGE:\n");
    for u in usage {
        s.push_str("    ");
        s.push_str(u);
        s.push('\n');
    }
    if !args.is_empty() {
        s.push('\n');
        let key_width = args.iter().map(|(k, _)| k.len()).max().unwrap_or(0);
        section(&mut s, "ARGS:", args, key_width);
    } else {
        s.push('\n');
    }
    let key_width = opts.iter().map(|(k, _)| k.len()).max().unwrap_or(0);
    section(&mut s, "OPTIONS:", opts, key_width);
    // Remove the extra trailing blank line added by section().
    while s.ends_with("\n\n") { s.pop(); }
    s
}

