fn line(cmd: &str, alias: Option<&str>, desc: &str, indent: usize) -> String {
    let mut s = String::new();
    for _ in 0..indent {
        s.push(' ');
    }
    s.push_str(BLUE);
    s.push_str(cmd);
    s.push_str(RESET);
    if let Some(a) = alias {
        s.push_str(", ");
        s.push_str(BLUE);
        s.push_str(a);
        s.push_str(RESET);
    }
    // The widest combined cmd+alias in the main help is 6+2+2 = 10
    // characters.  Columns align at that width.
    let combined = cmd.len() + 2 + alias.map(|a| a.len()).unwrap_or(0);
    let pad = 10usize.saturating_sub(combined);
    for _ in 0..pad {
        s.push(' ');
    }
    s.push_str("       ");
    s.push_str(desc);
    s.push('\n');
    s
}

fn section(s: &mut String, title: &str, items: &[(&str, &str)], key_width: usize) {
    s.push_str(title);
    s.push('\n');
    for (k, v) in items {
        s.push_str("    ");
        s.push_str(k);
        let pad = key_width.saturating_sub(k.len());
        for _ in 0..pad { s.push(' '); }
        s.push_str("    ");
        // Wrap long descriptions at roughly 91 columns to match clap.
        write_wrapped(s, v, key_width + 8);
        s.push('\n');
    }
    s.push('\n');
}

fn write_wrapped(s: &mut String, text: &str, first_col: usize) {
    // Break text into lines of up to 91 - first_col characters,
    // breaking on word boundaries, indenting continuation lines by
    // `first_col` spaces.
    let wrap = 91 - first_col;
    let words: Vec<&str> = text.split_whitespace().collect();
    let mut line = String::new();
    let mut first = true;
    for w in words {
        if !first && line.len() + 1 + w.len() > wrap {
            s.push_str(&line);
            s.push('\n');
            for _ in 0..first_col { s.push(' '); }
            line.clear();
            first = true;
        }
        if !first { line.push(' '); }
        line.push_str(w);
        first = false;
    }
    if !line.is_empty() { s.push_str(&line); }
}

fn clap_help(prog: &str, sub: &str, about: &str, usage: &[String],
             args: &[(&str, &str)], opts: &[(&str, &str)]) -> String {
    let mut s = String::new();
    s.push_str(prog);
    s.push('-');
    s.push_str(sub);
    s.push_str(" \n");
    s.push_str(about);
    s.push_str("\n\nUSAGE:\n");
    for u in usage {
        s.push_str("    ");
        s.push_str(u);
        s.push('\n');
    }
    if !args.is_empty() {
        s.push('\n');
        let key_width = args.iter().map(|(k, _)| k.len()).max().unwrap_or(0);
        section(&mut s, "ARGS:", args, key_width);
    } else {
        s.push('\n');
    }
    let key_width = opts.iter().map(|(k, _)| k.len()).max().unwrap_or(0);
    section(&mut s, "OPTIONS:", opts, key_width);
    // Remove the extra trailing blank line added by section().
    while s.ends_with("\n\n") { s.pop(); }
    s
}

