//! Command-line parser.  Reproduces the minimum clap-v3 behaviour
//! required by the reference binary: positional arguments, a single
//! boolean flag for `vault -l`, the stock `-h/--help` handling and
//! clap's distinctive error messages.

use crate::help;

/// Parsed command to execute.
pub enum Cmd {
    MainHelp,
    Vault { location_flag: bool, name: Option<String>, location: Option<String> },
    Note { name: String },
    Folder { name: String },
    Enter { name: String },
    Open { name: String },
    Opdir,
    Chdir { path: String },
    List { kind: Option<ListKind> },
    Remove { kind: ItemKind, name: String },
    Rename { kind: ItemKind, name: String, new_name: String },
    Move { kind: ItemKind, name: String, new_location: String },
    Vmove { kind: VaultItemKind, name: String, vault: String },
    Config { kind: Option<ConfigKind>, value: Option<String> },
    Help { sub: Option<String> },
}

#[derive(Clone, Copy)]
pub enum ItemKind { Vault, Note, Folder }

#[derive(Clone, Copy)]
pub enum VaultItemKind { Note, Folder }

#[derive(Clone, Copy)]
pub enum ListKind { Note, Folder }

#[derive(Clone, Copy)]
pub enum ConfigKind { Editor, Conflict }

pub enum ParseResult {
    Exec(Cmd),
    Help(String),
    Error(String),
}

/// Every subcommand and its aliases.  The first element is the
/// canonical name.
const SUBCOMMANDS: &[&[&str]] = &[
    &["vault", "vl"],
    &["note", "nt"],
    &["folder", "fd"],
    &["enter", "en"],
    &["open", "op"],
    &["opdir", "od"],
    &["chdir", "cd"],
    &["list", "ls"],
    &["remove", "rm"],
    &["rename", "rn"],
    &["move", "mv"],
    &["vmove", "vm"],
    &["config", "cf"],
    &["help"],
];

fn canonical(name: &str) -> Option<&'static str> {
    for group in SUBCOMMANDS {
        if group.iter().any(|g| *g == name) {
            return Some(group[0]);
        }
    }
    None
}

fn has_help_flag(args: &[String]) -> bool {
    args.iter().any(|a| a == "-h" || a == "--help")
}

pub fn parse(prog: &str, args: &[String]) -> ParseResult {
    if args.is_empty() {
        return ParseResult::Help(help::main_help());
    }
    let first = &args[0];
    if first == "-h" || first == "--help" {
        return ParseResult::Help(help::main_help());
    }
    let (sub, rest) = match canonical(first.as_str()) {
        Some(c) => (c, &args[1..]),
        None => {
            if first.starts_with('-') {
                return ParseResult::Error(unknown_arg(prog, first));
            }
            return ParseResult::Error(unknown_subcommand(prog, first));
        }
    };

    if has_help_flag(rest) && sub != "help" {
        return ParseResult::Help(help_for(prog, sub));
    }

    match sub {
        "vault" => parse_vault(prog, rest),
        "note" => parse_note(prog, rest),
        "folder" => parse_folder(prog, rest),
        "enter" => parse_enter(prog, rest),
        "open" => parse_open(prog, rest),
        "opdir" => parse_opdir(prog, rest),
        "chdir" => parse_chdir(prog, rest),
        "list" => parse_list(prog, rest),
        "remove" => parse_remove(prog, rest),
        "rename" => parse_rename(prog, rest),
        "move" => parse_move(prog, rest),
        "vmove" => parse_vmove(prog, rest),
        "config" => parse_config(prog, rest),
        "help" => parse_help(prog, rest),
        _ => unreachable!(),
    }
}

pub fn help_for(prog: &str, sub: &str) -> String {
    match sub {
        "vault" => help::vault(prog),
        "note" => help::note(prog),
        "folder" => help::folder(prog),
        "enter" => help::enter(prog),
        "open" => help::open(prog),
        "opdir" => help::opdir(prog),
        "chdir" => help::chdir(prog),
        "list" => help::list(prog),
        "remove" => help::remove(prog),
        "rename" => help::rename(prog),
        "move" => help::move_cmd(prog),
        "vmove" => help::vmove(prog),
        "config" => help::config(prog),
        "help" => help::help(prog),
        _ => unreachable!(),
    }
}

// -----------------------------------------------------------------
//  Clap-style error strings
// -----------------------------------------------------------------

fn unknown_subcommand(prog: &str, name: &str) -> String {
    // Only suggest for a small set of similar names; matching the
    // reference's "Did you mean 'note'?" tip would require a full
    // clap-v3 replication, which we skip.
    let mut s = String::new();
    s.push_str(&format!(
        "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n    {} <SUBCOMMAND>\n\nFor more information try --help\n",
        name, prog
    ));
    s
}

fn unknown_arg(prog: &str, arg: &str) -> String {
    format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n\nUSAGE:\n    {} <SUBCOMMAND>\n\nFor more information try --help\n",
        arg, arg, arg, prog
    )
}

fn missing_arg(usage: &[String], required: &str) -> String {
    let mut s = String::new();
    s.push_str("error: The following required arguments were not provided:\n    ");
    s.push_str(required);
    s.push_str("\n\nUSAGE:\n");
    for u in usage {
        s.push_str("    ");
        s.push_str(u);
        s.push('\n');
    }
    s.push_str("\nFor more information try --help\n");
    s
}

fn requires_value(usage: &[String], name: &str) -> String {
    let mut s = String::new();
    s.push_str(&format!(
        "error: The argument '{}' requires a value but none was supplied\n\nFor more information try --help\n",
        name
    ));
    let _ = usage;
    s
}

fn invalid_value(name: &str, value: &str, possible: &[&str]) -> String {
    let mut s = String::new();
    s.push_str(&format!("error: \"{}\" isn't a valid value for '{}'\n", value, name));
    s.push_str("\t[possible values: ");
    for (i, v) in possible.iter().enumerate() {
        if i > 0 { s.push_str(", "); }
        s.push_str(v);
