fn parse_vault(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![
        "jt vault".to_string(),
        "jt vault -l".to_string(),
        "jt vault <vault name> <vault location>".to_string(),
    ];
    let mut positional: Vec<String> = Vec::new();
    let mut location_flag = false;
    for a in args {
        if a == "-l" {
            location_flag = true;
        } else if a.starts_with('-') {
            let _ = prog;
            return ParseResult::Error(unexpected_arg(&usage, a));
        } else {
            positional.push(a.clone());
        }
    }
    if positional.is_empty() {
        return ParseResult::Exec(Cmd::Vault { location_flag, name: None, location: None });
    }
    if positional.len() == 1 {
        return ParseResult::Error(missing_arg(&usage, "<vault location>"));
    }
    if positional.len() > 2 {
        return ParseResult::Error(unexpected_arg(&usage, &positional[2]));
    }
    ParseResult::Exec(Cmd::Vault {
        location_flag,
        name: Some(positional[0].clone()),
        location: Some(positional[1].clone()),
    })
}

fn parse_note(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec!["jt note".to_string(), "jt note [note name]".to_string()];
    let _ = prog;
    let positional: Vec<String> = args.iter().filter(|a| !a.is_empty() || true).cloned().collect();
    // The reference binary rejects `-x` as unexpected, unless it's
    // exactly `-h/--help` (handled above).
    for a in &positional {
        if a.starts_with('-') && a != "--" {
            return ParseResult::Error(unexpected_arg(&usage, a));
