        return ParseResult::Exec(Cmd::Config { kind: Some(kind), value: None });
    }
    if args.len() > 2 {
        return ParseResult::Error(unexpected_arg(&usage, &args[2]));
    }
    ParseResult::Exec(Cmd::Config { kind: Some(kind), value: Some(args[1].clone()) })
}

fn parse_help(prog: &str, args: &[String]) -> ParseResult {
    if args.is_empty() {
        return ParseResult::Help(help::main_help());
    }
    let sub = &args[0];
    if canonical(sub.as_str()).is_none() {
        return ParseResult::Error(unknown_subcommand(prog, sub));
