//! Command-line parser.  Reproduces the minimum clap-v3 behaviour
//! required by the reference binary: positional arguments, a single
//! boolean flag for `vault -l`, the stock `-h/--help` handling and
//! clap's distinctive error messages.

use crate::help;

/// Parsed command to execute.
pub enum Cmd {
    MainHelp,
    Vault { location_flag: bool, name: Option<String>, location: Option<String> },
    Note { name: String },
    Folder { name: String },
    Enter { name: String },
    Open { name: String },
    Opdir,
    Chdir { path: String },
    List { kind: Option<ListKind> },
    Remove { kind: ItemKind, name: String },
    Rename { kind: ItemKind, name: String, new_name: String },
    Move { kind: ItemKind, name: String, new_location: String },
    Vmove { kind: VaultItemKind, name: String, vault: String },
    Config { kind: Option<ConfigKind>, value: Option<String> },
    Help { sub: Option<String> },
}

#[derive(Clone, Copy)]
pub enum ItemKind { Vault, Note, Folder }

#[derive(Clone, Copy)]
pub enum VaultItemKind { Note, Folder }

#[derive(Clone, Copy)]
pub enum ListKind { Note, Folder }

#[derive(Clone, Copy)]
pub enum ConfigKind { Editor, Conflict }

pub enum ParseResult {
    Exec(Cmd),
    Help(String),
    Error(String),
}

/// Every subcommand and its aliases.  The first element is the
/// canonical name.
const SUBCOMMANDS: &[&[&str]] = &[
    &["vault", "vl"],
    &["note", "nt"],
    &["folder", "fd"],
    &["enter", "en"],
    &["open", "op"],
    &["opdir", "od"],
    &["chdir", "cd"],
    &["list", "ls"],
    &["remove", "rm"],
    &["rename", "rn"],
    &["move", "mv"],
    &["vmove", "vm"],
    &["config", "cf"],
    &["help"],
];

fn canonical(name: &str) -> Option<&'static str> {
    for group in SUBCOMMANDS {
        if group.iter().any(|g| *g == name) {
            return Some(group[0]);
        }
    }
    None
}

fn has_help_flag(args: &[String]) -> bool {
    args.iter().any(|a| a == "-h" || a == "--help")
}

pub fn parse(prog: &str, args: &[String]) -> ParseResult {
    if args.is_empty() {
        return ParseResult::Help(help::main_help());
    }
    let first = &args[0];
    if first == "-h" || first == "--help" {
        return ParseResult::Help(help::main_help());
    }
    let (sub, rest) = match canonical(first.as_str()) {
        Some(c) => (c, &args[1..]),
        None => {
            if first.starts_with('-') {
                return ParseResult::Error(unknown_arg(prog, first));
            }
            return ParseResult::Error(unknown_subcommand(prog, first));
        }
    };

    if has_help_flag(rest) && sub != "help" {
        return ParseResult::Help(help_for(prog, sub));
    }

    match sub {
        "vault" => parse_vault(prog, rest),
        "note" => parse_note(prog, rest),
        "folder" => parse_folder(prog, rest),
        "enter" => parse_enter(prog, rest),
        "open" => parse_open(prog, rest),
        "opdir" => parse_opdir(prog, rest),
        "chdir" => parse_chdir(prog, rest),
        "list" => parse_list(prog, rest),
        "remove" => parse_remove(prog, rest),
        "rename" => parse_rename(prog, rest),
        "move" => parse_move(prog, rest),
        "vmove" => parse_vmove(prog, rest),
        "config" => parse_config(prog, rest),
        "help" => parse_help(prog, rest),
        _ => unreachable!(),
    }
}

pub fn help_for(prog: &str, sub: &str) -> String {
    match sub {
        "vault" => help::vault(prog),
        "note" => help::note(prog),
        "folder" => help::folder(prog),
        "enter" => help::enter(prog),
        "open" => help::open(prog),
        "opdir" => help::opdir(prog),
        "chdir" => help::chdir(prog),
        "list" => help::list(prog),
        "remove" => help::remove(prog),
        "rename" => help::rename(prog),
        "move" => help::move_cmd(prog),
        "vmove" => help::vmove(prog),
        "config" => help::config(prog),
        "help" => help::help(prog),
        _ => unreachable!(),
    }
}

// -----------------------------------------------------------------
//  Clap-style error strings
// -----------------------------------------------------------------

fn unknown_subcommand(prog: &str, name: &str) -> String {
    // Only suggest for a small set of similar names; matching the
    // reference's "Did you mean 'note'?" tip would require a full
    // clap-v3 replication, which we skip.
    let mut s = String::new();
    s.push_str(&format!(
        "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n    {} <SUBCOMMAND>\n\nFor more information try --help\n",
        name, prog
    ));
    s
}

fn unknown_arg(prog: &str, arg: &str) -> String {
    format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n\nUSAGE:\n    {} <SUBCOMMAND>\n\nFor more information try --help\n",
        arg, arg, arg, prog
    )
}

fn missing_arg(usage: &[String], required: &str) -> String {
    let mut s = String::new();
    s.push_str("error: The following required arguments were not provided:\n    ");
    s.push_str(required);
    s.push_str("\n\nUSAGE:\n");
    for u in usage {
        s.push_str("    ");
        s.push_str(u);
        s.push('\n');
    }
    s.push_str("\nFor more information try --help\n");
    s
}

fn requires_value(usage: &[String], name: &str) -> String {
    let mut s = String::new();
    s.push_str(&format!(
        "error: The argument '{}' requires a value but none was supplied\n\nFor more information try --help\n",
        name
    ));
    let _ = usage;
    s
}

fn invalid_value(name: &str, value: &str, possible: &[&str]) -> String {
    let mut s = String::new();
    s.push_str(&format!("error: \"{}\" isn't a valid value for '{}'\n", value, name));
    s.push_str("\t[possible values: ");
    for (i, v) in possible.iter().enumerate() {
        if i > 0 { s.push_str(", "); }
        s.push_str(v);
    }
    s.push_str("]\n\nFor more information try --help\n");
    s
}

fn unexpected_arg(usage: &[String], arg: &str) -> String {
    let mut s = String::new();
    s.push_str(&format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
        arg
    ));
    if arg.starts_with('-') {
        s.push_str(&format!("\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n", arg, arg));
    }
    s.push_str("\nUSAGE:\n");
    for u in usage {
        s.push_str("    ");
        s.push_str(u);
        s.push('\n');
    }
    s.push_str("\nFor more information try --help\n");
    s
}

// -----------------------------------------------------------------
//  Individual subcommand parsers
// -----------------------------------------------------------------

fn parse_vault(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![
        "jt vault".to_string(),
        "jt vault -l".to_string(),
        "jt vault <vault name> <vault location>".to_string(),
    ];
    let mut positional: Vec<String> = Vec::new();
    let mut location_flag = false;
    for a in args {
        if a == "-l" {
            location_flag = true;
        } else if a.starts_with('-') {
            let _ = prog;
            return ParseResult::Error(unexpected_arg(&usage, a));
        } else {
            positional.push(a.clone());
        }
    }
    if positional.is_empty() {
        return ParseResult::Exec(Cmd::Vault { location_flag, name: None, location: None });
    }
    if positional.len() == 1 {
        return ParseResult::Error(missing_arg(&usage, "<vault location>"));
    }
    if positional.len() > 2 {
        return ParseResult::Error(unexpected_arg(&usage, &positional[2]));
    }
    ParseResult::Exec(Cmd::Vault {
        location_flag,
        name: Some(positional[0].clone()),
        location: Some(positional[1].clone()),
    })
}

fn parse_note(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec!["jt note".to_string(), "jt note [note name]".to_string()];
    let _ = prog;
    let positional: Vec<String> = args.iter().filter(|a| !a.is_empty() || true).cloned().collect();
    // The reference binary rejects `-x` as unexpected, unless it's
    // exactly `-h/--help` (handled above).
    for a in &positional {
        if a.starts_with('-') && a != "--" {
            return ParseResult::Error(unexpected_arg(&usage, a));
        }
    }
    if positional.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<note name>"));
    }
    if positional.len() > 1 {
        return ParseResult::Error(unexpected_arg(&usage, &positional[1]));
    }
    ParseResult::Exec(Cmd::Note { name: positional[0].clone() })
}

fn parse_folder(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec!["jt folder".to_string(), "jt folder [folder name]".to_string()];
    let _ = prog;
    let positional: Vec<String> = args.iter().cloned().collect();
    for a in &positional {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if positional.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<folder name>"));
    }
    if positional.len() > 1 {
        return ParseResult::Error(unexpected_arg(&usage, &positional[1]));
    }
    ParseResult::Exec(Cmd::Folder { name: positional[0].clone() })
}

fn parse_enter(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} enter <vault name>", prog)];
    for a in args {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if args.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<vault name>"));
    }
    if args.len() > 1 {
        return ParseResult::Error(unexpected_arg(&usage, &args[1]));
    }
    ParseResult::Exec(Cmd::Enter { name: args[0].clone() })
}

fn parse_open(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} open <note name>", prog)];
    for a in args {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if args.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<note name>"));
    }
    if args.len() > 1 {
        return ParseResult::Error(unexpected_arg(&usage, &args[1]));
    }
    ParseResult::Exec(Cmd::Open { name: args[0].clone() })
}

fn parse_opdir(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} opdir", prog)];
    if let Some(a) = args.get(0) {
        return ParseResult::Error(unexpected_arg(&usage, a));
    }
    ParseResult::Exec(Cmd::Opdir)
}

fn parse_chdir(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} chdir <folder path>", prog)];
    if args.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<folder path>"));
    }
    if args[0].is_empty() {
        return ParseResult::Error(requires_value(&usage, "<folder path>"));
    }
    if args.len() > 1 {
        return ParseResult::Error(unexpected_arg(&usage, &args[1]));
    }
    ParseResult::Exec(Cmd::Chdir { path: args[0].clone() })
}

fn parse_list(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} list [item type]", prog)];
    for a in args {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if args.is_empty() {
        return ParseResult::Exec(Cmd::List { kind: None });
    }
    if args.len() > 1 {
        return ParseResult::Error(unexpected_arg(&usage, &args[1]));
    }
    let kind = match args[0].as_str() {
        "note" | "nt" => ListKind::Note,
        "folder" | "fd" => ListKind::Folder,
        other => {
            return ParseResult::Error(invalid_value("<item type>", other, &["note", "nt", "folder", "fd"]));
        }
    };
    ParseResult::Exec(Cmd::List { kind: Some(kind) })
}

fn parse_item_kind(v: &str) -> Option<ItemKind> {
    match v {
        "vault" | "vl" => Some(ItemKind::Vault),
        "note" | "nt" => Some(ItemKind::Note),
        "folder" | "fd" => Some(ItemKind::Folder),
        _ => None,
    }
}

fn parse_vault_item_kind(v: &str) -> Option<VaultItemKind> {
    match v {
        "note" | "nt" => Some(VaultItemKind::Note),
        "folder" | "fd" => Some(VaultItemKind::Folder),
        _ => None,
    }
}

fn parse_remove(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} remove <item type> <name>", prog)];
    for a in args {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if args.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<item type>\n    <name>"));
    }
    let kind = match parse_item_kind(&args[0]) {
        Some(k) => k,
        None => return ParseResult::Error(invalid_value("<item type>", &args[0], &["vault", "vl", "note", "nt", "folder", "fd"])),
    };
    if args.len() == 1 {
        return ParseResult::Error(missing_arg(&usage, "<name>"));
    }
    if args.len() > 2 {
        return ParseResult::Error(unexpected_arg(&usage, &args[2]));
    }
    ParseResult::Exec(Cmd::Remove { kind, name: args[1].clone() })
}

fn parse_rename(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} rename <item type> <name> <new name>", prog)];
    for a in args {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if args.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<item type>\n    <name>\n    <new name>"));
    }
    let kind = match parse_item_kind(&args[0]) {
        Some(k) => k,
        None => return ParseResult::Error(invalid_value("<item type>", &args[0], &["vault", "vl", "note", "nt", "folder", "fd"])),
    };
    if args.len() < 2 {
        return ParseResult::Error(missing_arg(&usage, "<name>\n    <new name>"));
    }
    if args.len() < 3 {
        return ParseResult::Error(missing_arg(&usage, "<new name>"));
    }
    if args.len() > 3 {
        return ParseResult::Error(unexpected_arg(&usage, &args[3]));
    }
    ParseResult::Exec(Cmd::Rename { kind, name: args[1].clone(), new_name: args[2].clone() })
}

fn parse_move(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} move <item type> <name> <new location>", prog)];
    for a in args {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if args.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<item type>\n    <name>\n    <new location>"));
    }
    let kind = match parse_item_kind(&args[0]) {
        Some(k) => k,
        None => return ParseResult::Error(invalid_value("<item type>", &args[0], &["vault", "vl", "note", "nt", "folder", "fd"])),
    };
    if args.len() < 2 {
        return ParseResult::Error(missing_arg(&usage, "<name>\n    <new location>"));
    }
    if args.len() < 3 {
        return ParseResult::Error(missing_arg(&usage, "<new location>"));
    }
    if args.len() > 3 {
        return ParseResult::Error(unexpected_arg(&usage, &args[3]));
    }
    ParseResult::Exec(Cmd::Move { kind, name: args[1].clone(), new_location: args[2].clone() })
}

fn parse_vmove(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![format!("{} vmove <item type> <name> <vault name>", prog)];
    for a in args {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if args.is_empty() {
        return ParseResult::Error(missing_arg(&usage, "<item type>\n    <name>\n    <vault name>"));
    }
    let kind = match parse_vault_item_kind(&args[0]) {
        Some(k) => k,
        None => return ParseResult::Error(invalid_value("<item type>", &args[0], &["note", "nt", "folder", "fd"])),
    };
    if args.len() < 2 {
        return ParseResult::Error(missing_arg(&usage, "<name>\n    <vault name>"));
    }
    if args.len() < 3 {
        return ParseResult::Error(missing_arg(&usage, "<vault name>"));
    }
    if args.len() > 3 {
        return ParseResult::Error(unexpected_arg(&usage, &args[3]));
    }
    ParseResult::Exec(Cmd::Vmove { kind, name: args[1].clone(), vault: args[2].clone() })
}

fn parse_config(prog: &str, args: &[String]) -> ParseResult {
    let usage = vec![
        "jt config <config type>".to_string(),
        "jt config <config type> [config value]".to_string(),
    ];
    let _ = prog;
    for a in args {
        if a.starts_with('-') { return ParseResult::Error(unexpected_arg(&usage, a)); }
    }
    if args.is_empty() {
        return ParseResult::Exec(Cmd::Config { kind: None, value: None });
    }
    let kind = match args[0].as_str() {
        "editor" => ConfigKind::Editor,
        "conflict" => ConfigKind::Conflict,
        other => {
            return ParseResult::Error(invalid_value("<config type>", other, &["editor", "conflict"]));
        }
    };
    if args.len() == 1 {
        return ParseResult::Exec(Cmd::Config { kind: Some(kind), value: None });
    }
    if args.len() > 2 {
        return ParseResult::Error(unexpected_arg(&usage, &args[2]));
    }
    ParseResult::Exec(Cmd::Config { kind: Some(kind), value: Some(args[1].clone()) })
}

fn parse_help(prog: &str, args: &[String]) -> ParseResult {
    if args.is_empty() {
        return ParseResult::Help(help::main_help());
    }
    let sub = &args[0];
    if canonical(sub.as_str()).is_none() {
        return ParseResult::Error(unknown_subcommand(prog, sub));
    }
    let c = canonical(sub.as_str()).unwrap();
    ParseResult::Help(help_for(prog, c))
}
