        Cmd::Move { kind, name, new_location } => mv::run(kind, &name, &new_location),
        Cmd::Vmove { kind, name, vault } => vmove::run(kind, &name, &vault),
        Cmd::Config { kind, value } => config::run(kind, value),
        Cmd::Help { sub } => helpc::run(prog, sub),
    }
}
