pub fn run(prog: &str, cmd: Cmd) -> Result<(), AppError> {
    match cmd {
        Cmd::MainHelp => Ok(()),
        Cmd::Vault { location_flag, name, location } => vault::run(location_flag, name, location),
        Cmd::Note { name } => note::run(&name),
        Cmd::Folder { name } => folder::run(&name),
        Cmd::Enter { name } => enter::run(&name),
        Cmd::Open { name } => open::run(&name),
        Cmd::Opdir => opdir::run(),
        Cmd::Chdir { path } => chdir::run(&path),
        Cmd::List { kind } => list::run(kind),
        Cmd::Remove { kind, name } => remove::run(kind, &name),
        Cmd::Rename { kind, name, new_name } => rename::run(kind, &name, &new_name),
        Cmd::Move { kind, name, new_location } => mv::run(kind, &name, &new_location),
        Cmd::Vmove { kind, name, vault } => vmove::run(kind, &name, &vault),
        Cmd::Config { kind, value } => config::run(kind, value),
        Cmd::Help { sub } => helpc::run(prog, sub),
