use std::fs;
use std::path::{Path, PathBuf};

use crate::error::{AppError, BLUE, RESET};
use crate::state::{Vaults, VaultData};

pub fn run(location_flag: bool, name: Option<String>, location: Option<String>)
    -> Result<(), AppError>
{
    match (name, location) {
        (Some(n), Some(l)) => create(&n, &l),
        (None, None) => list(location_flag),
        _ => Ok(()),
    }
}

fn list(location_flag: bool) -> Result<(), AppError> {
    let vaults = Vaults::load();
    let current = vaults.current();
    for (name, loc) in vaults.list() {
        let is_current = Some(&name) == current.as_ref();
        let prefix = if is_current { "\u{1F449} " } else { "   " };
        let display_name = if is_current {
            format!("{}{}{}", BLUE, name, RESET)
        } else {
            name.clone()
        };
        if location_flag {
            println!("{}{} \t {}", prefix, display_name, loc);
        } else {
            println!("{}{}", prefix, display_name);
        }
    }
    Ok(())
}

fn create(name: &str, location: &str) -> Result<(), AppError> {
    if crate::fsutil::name_is_invalid(name) {
        return Err(AppError::new("invalid name"));
    }
    if !Path::new(location).is_absolute() {
        return Err(AppError::new("specified path isn't absolute"));
    }
    if !Path::new(location).exists() {
        return Err(AppError::new("couldn't find the path specified"));
    }
    let mut vaults = Vaults::load();
    if vaults.contains(name) {
        return Err(AppError::new(format!("vault {} already exists", name)));
    }
    // Do not create if something with the new name already exists
    // under the target location.
    let vault_dir: PathBuf = Path::new(location).join(name);
    if vault_dir.exists() {
        return Err(AppError::new(format!(
            "a folder named {} already exists in this location", name
        )));
    }
    fs::create_dir_all(vault_dir.join(".jot"))
        .map_err(|e| AppError::new(format!("io error: {}", e)))?;
    let data = VaultData::new(name, location);
    data.save().map_err(|e| AppError::new(format!("io error: {}", e)))?;
    vaults.add(name, location);
    vaults.save();
    println!("vault {}{}{} created", BLUE, name, RESET);
    Ok(())
}
EOF
