    }
    let cfg = Config::load();
    let editor = cfg.editor();
    if editor.is_empty() {
        return Err(AppError::new("editor not found"));
    }
    run_editor(&editor, Path::new(&path))
}

pub(crate) fn run_editor(editor: &str, target: &std::path::Path) -> Result<(), AppError> {
    // Tokenise the editor command as a shell would for a simple case
    // (split by whitespace).  This lets users set e.g. "code -w".
    let parts: Vec<&str> = editor.split_whitespace().collect();
    if parts.is_empty() {
        return Err(AppError::new("editor not found"));
    }
    let status = Command::new(parts[0])
        .args(&parts[1..])
        .arg(target)
        .status();
    match status {
        Ok(_) => Ok(()),
        Err(_) => Err(AppError::new("editor not found")),
    }
}
