use crate::cli::ItemKind;
use crate::error::{AppError, BLUE, RESET};
use crate::fsutil::{name_is_invalid, note_filename};
use crate::state::{Vaults, VaultData};

pub fn run(kind: ItemKind, name: &str, new_name: &str) -> Result<(), AppError> {
    if name_is_invalid(new_name) {
        return Err(AppError::new("invalid name"));
    }
    if name == new_name {
        return Err(AppError::new("new name is same as old name"));
    }
    match kind {
