use crate::error::{AppError, BLUE, RESET};
use crate::fsutil::{move_item, note_filename, resolve_folder_path};
use crate::state::{Vaults, VaultData};

pub fn run(kind: ItemKind, name: &str, new_location: &str) -> Result<(), AppError> {
    match kind {
        ItemKind::Vault => move_vault(name, new_location),
        ItemKind::Note => move_note(name, new_location),
        ItemKind::Folder => move_folder(name, new_location),
    }
}

fn move_vault(name: &str, new_location: &str) -> Result<(), AppError> {
    let mut vaults = Vaults::load();
    let old_location = match vaults.location_of(name) {
        Some(l) => l,
        None => return Err(AppError::new(format!("vault {} doesn't exist", name))),
    };
    let new_path = Path::new(new_location);
    if !new_path.is_absolute() {
        return Err(AppError::new("specified path isn't absolute"));
    }
    if !new_path.exists() {
        return Err(AppError::new(format!(
            "no such file or directory (os error 2)"
        )));
    }
    if old_location == new_location {
        return Err(AppError::new("new location is same as old location"));
    }
    let target = new_path.join(name);
    if target.exists() {
        return Err(AppError::new(format!("a folder named {} already exists in this location", name)));
    }
    let src = Path::new(&old_location).join(name);
    move_item(&src, &target).map_err(|e| AppError::new(format!("io error: {}", e)))?;
    vaults.add(name, new_location);
    vaults.save();
    let mut data = VaultData::load(new_location, name)?;
    data.location = new_location.to_string();
    let _ = data.save();
    println!("vault {}{}{} moved", BLUE, name, RESET);
    Ok(())
}

fn require_current() -> Result<(String, String), AppError> {
    let vaults = Vaults::load();
    let current = vaults.current().ok_or_else(|| AppError::new("not inside a vault"))?;
    let location = vaults.location_of(&current).ok_or_else(|| AppError::new("not inside a vault"))?;
    Ok((current, location))
}

fn resolve_target_dir(data: &VaultData, new_location: &str) -> Result<PathBuf, AppError> {
    let folder = resolve_folder_path(&data.folder, new_location)?;
    let root = data.vault_root();
    let path = if folder.is_empty() { root } else { root.join(&folder) };
    if !path.is_dir() {
        return Err(AppError::new("couldn't find the path specified"));
    }
    Ok(path)
}

fn move_note(name: &str, new_location: &str) -> Result<(), AppError> {
    let (current, location) = require_current()?;
    let data = VaultData::load(&location, &current)?;
    let cur_dir = data.current_path();
    let file = note_filename(name);
    let src = cur_dir.join(&file);
    if !src.exists() || src.is_dir() {
        return Err(AppError::new("couldn't find the path specified"));
    }
    let target_dir = resolve_target_dir(&data, new_location)?;
    if target_dir == cur_dir {
        return Err(AppError::new("new location is same as old location"));
    }
    let target = target_dir.join(&file);
    if target.exists() {
        return Err(AppError::new(format!("a note named {} already exists in this location", name)));
    }
    fs::rename(&src, &target).map_err(|_| AppError::new("io error"))?;
    println!("note {}{}{} moved", BLUE, name, RESET);
    Ok(())
}

fn move_folder(name: &str, new_location: &str) -> Result<(), AppError> {
    let (current, location) = require_current()?;
    let data = VaultData::load(&location, &current)?;
    let cur_dir = data.current_path();
    let src = cur_dir.join(name);
    if !src.exists() || !src.is_dir() {
        return Err(AppError::new("couldn't find the path specified"));
    }
    let target_dir = resolve_target_dir(&data, new_location)?;
    if target_dir == cur_dir {
        return Err(AppError::new("new location is same as old location"));
    }
    let target = target_dir.join(name);
    if target.exists() {
        return Err(AppError::new(format!("a folder named {} already exists in this location", name)));
    }
    move_item(&src, &target).map_err(|_| AppError::new("io error"))?;
    println!("folder {}{}{} moved", BLUE, name, RESET);
    Ok(())
}
