use std::path::Path;

use crate::cli::VaultItemKind;
use crate::error::{AppError, BLUE, RESET};
use crate::fsutil::{move_item, note_filename};
use crate::state::{Vaults, VaultData};

pub fn run(kind: VaultItemKind, name: &str, vault: &str) -> Result<(), AppError> {
    let vaults = Vaults::load();
    let current = vaults.current().ok_or_else(|| AppError::new("not inside a vault"))?;
    let src_location = vaults.location_of(&current).ok_or_else(|| AppError::new("not inside a vault"))?;

    let (label, file) = match kind {
        VaultItemKind::Note => ("note", note_filename(name)),
        VaultItemKind::Folder => ("folder", name.to_string()),
    };

    // Match the reference binary's quirky error path: when the
    // destination is the current vault, emit a compound message that
    // includes the "already exists" text, regardless of whether it
    // does.  (The output uses the item name even if no such file
    // exists on disk.)
    if current == vault {
        let prefix = format!("{} {} already exists in vault {}", label, name, current);
        return Err(AppError::composite(prefix, "new location is same as old location"));
    }

    // If the target vault isn't registered the reference binary
    // reports "vault <name> doesn't exist" using the *item* name.
    if !vaults.contains(vault) {
        return Err(AppError::new(format!("vault {} doesn't exist", name)));
    }
    let dst_location = vaults.location_of(vault).unwrap();

    let src_data = VaultData::load(&src_location, &current)?;
    let src_path = src_data.current_path().join(&file);
    if !src_path.exists() {
        return Err(AppError::new("no such file or directory (os error 2)"));
    }

    let dst_data = VaultData::load(&dst_location, vault)?;
    let dst_folder = dst_data.vault_root();
    let dst_path = dst_folder.join(&file);
    if dst_path.exists() {
        return Err(AppError::new(format!("a {} named {} already exists in this location", label, name)));
    }
    move_item(&src_path, &dst_path).map_err(|e| AppError::new(format!("io error: {}", e)))?;
    let _ = Path::new("/"); // keep Path import used
    println!("{} {}{}{} moved to vault {}{}{}", label, BLUE, name, RESET, BLUE, vault, RESET);
    Ok(())
}
