use crate::cli::ConfigKind;
use crate::error::{AppError, BLUE, RESET};
use crate::state::Config;
use crate::toml_lite::Value;

pub fn run(kind: Option<ConfigKind>, value: Option<String>) -> Result<(), AppError> {
    match (kind, value) {
        (None, _) => open_in_editor(),
        (Some(k), None) => display(k),
        (Some(k), Some(v)) => set_value(k, &v),
    }
}

fn display(kind: ConfigKind) -> Result<(), AppError> {
    let cfg = Config::load();
    let (name, value) = match kind {
        ConfigKind::Editor => ("editor", cfg.editor()),
        ConfigKind::Conflict => ("conflict", cfg.conflict().to_string()),
    };
    println!("{}: {}{}{}", name, BLUE, value, RESET);
    Ok(())
}

fn set_value(kind: ConfigKind, value: &str) -> Result<(), AppError> {
    let mut cfg = Config::load();
    let (name, stored) = match kind {
        ConfigKind::Editor => ("editor", Value::Str(value.to_string())),
        ConfigKind::Conflict => {
            // Mirror the original's panic-on-ParseBoolError behaviour.
            let parsed: bool = value
                .parse()
                .map_err(|_| AppError::new(format!("invalid boolean value '{}'", value)))?;
            ("conflict", Value::Bool(parsed))
        }
    };
    cfg.doc.set(name, stored);
    cfg.save();
    println!("set {}{}{} to {}{}{}", BLUE, name, RESET, BLUE, value, RESET);
    Ok(())
}

fn open_in_editor() -> Result<(), AppError> {
    let cfg = Config::load();
    let editor = cfg.editor();
    if editor.is_empty() {
        return Err(AppError::new("editor not found"));
    }
    crate::commands::open::run_editor(&editor, &crate::state::config_path())
}
