// jot - a terminal-focused note management tool.

mod cli;
mod error;
mod fsutil;
mod help;
mod state;
mod toml_lite;
mod tree;

mod commands;

use std::env;
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let program = args.get(0).cloned().unwrap_or_else(|| "executable".into());
    let prog = program
        .rsplit('/')
        .next()
        .unwrap_or("executable")
        .to_string();

    // Ensure default state files exist on every invocation.  This
    // mirrors the reference binary, which touches them on startup.
    let _ = state::Config::load();
    let _ = state::Vaults::load();

    match cli::parse(&prog, &args[1..]) {
        cli::ParseResult::Exec(cmd) => match commands::run(&prog, cmd) {
            Ok(()) => ExitCode::from(0),
            Err(e) => {
                e.print();
                ExitCode::from(0)
            }
        },
        cli::ParseResult::Help(text) => {
            print!("{}", text);
            ExitCode::from(0)
        }
        cli::ParseResult::Error(text) => {
            eprint!("{}", text);
            ExitCode::from(2)
        }
    }
}
EOF
