    }
    move_item(&src_path, &dst_path).map_err(|e| AppError::new(format!("io error: {}", e)))?;
    println!("{} {}{}{} moved to vault {}{}{}", label, BLUE, name, RESET, BLUE, vault, RESET);
    Ok(())
}

fn format_plain(s: &str) -> String {
