cat > /workspace/src/strsim.rs <<'EOF'
//! Minimal Jaro-Winkler similarity used for clap-style typo
//! suggestions in the subcommand dispatch.

pub fn jaro(a: &str, b: &str) -> f64 {
    if a == b { return 1.0; }
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    if ac.is_empty() || bc.is_empty() { return 0.0; }
    let match_distance = std::cmp::max(ac.len(), bc.len()) / 2;
    let match_distance = if match_distance == 0 { 0 } else { match_distance - 1 };
    let mut a_match = vec![false; ac.len()];
    let mut b_match = vec![false; bc.len()];
    let mut matches = 0;
    for i in 0..ac.len() {
        let start = i.saturating_sub(match_distance);
        let end = std::cmp::min(i + match_distance + 1, bc.len());
        for j in start..end {
            if b_match[j] { continue; }
            if ac[i] != bc[j] { continue; }
            a_match[i] = true;
            b_match[j] = true;
            matches += 1;
            break;
        }
    }
    if matches == 0 { return 0.0; }
    let mut transpositions = 0;
    let mut k = 0;
    for i in 0..ac.len() {
        if !a_match[i] { continue; }
        while !b_match[k] { k += 1; }
        if ac[i] != bc[k] { transpositions += 1; }
        k += 1;
    }
    let m = matches as f64;
    (m / ac.len() as f64
     + m / bc.len() as f64
     + (m - transpositions as f64 / 2.0) / m) / 3.0
}

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    let mut l = 0;
    let limit = std::cmp::min(std::cmp::min(ac.len(), bc.len()), 4);
    for i in 0..limit {
        if ac[i] == bc[i] { l += 1; } else { break; }
    }
    j + (l as f64) * 0.1 * (1.0 - j)
}
EOF
