python3 <<'EOF'
import re
path = "/workspace/src/cli.rs"
with open(path) as f:
    src = f.read()

old = """fn unknown_subcommand(prog: &str, name: &str) -> String {
    // Only suggest for a small set of similar names; matching the
    // reference's "Did you mean 'note'?" tip would require a full
    // clap-v3 replication, which we skip.
    let mut s = String::new();
    s.push_str(&format!(
        "error: The subcommand '{}' wasn't recognized\\n\\nUSAGE:\\n    {} <SUBCOMMAND>\\n\\nFor more information try --help\\n",
        name, prog
    ));
    s
}"""

new = """fn unknown_subcommand(prog: &str, name: &str) -> String {
    // Mirror clap's typo suggestions: use Jaro-Winkler similarity to
    // offer a hint when the argument is close to a registered
    // subcommand.  If nothing is similar enough we fall back to the
    // generic \"Found argument\" error.
    let mut suggestions: Vec<(&str, f64)> = Vec::new();
    for group in SUBCOMMANDS {
        for &alias in group.iter() {
            let score = crate::strsim::jaro_winkler(name, alias);
            if score > 0.7 {
                suggestions.push((alias, score));
            }
        }
    }
    if suggestions.is_empty() {
        return unknown_arg(prog, name);
    }
    // Sort descending by score; break ties by shorter string first.
    suggestions.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
    let hints: Vec<&str> = suggestions.iter().map(|(s, _)| *s).collect();
    let did_you_mean = if hints.len() == 1 {
        format!("'{}'", hints[0])
    } else {
        format!("'{}' or '{}'", hints[0], hints[1])
    };
    let mut s = String::new();
    s.push_str(&format!(
        "error: The subcommand '{}' wasn't recognized\\n\\n\\tDid you mean {}?\\n\\nIf you believe you received this message in error, try re-running with '{} -- {}'\\n\\nUSAGE:\\n    {} <SUBCOMMAND>\\n\\nFor more information try --help\\n",
        name, did_you_mean, prog, name, prog,
    ));
    s
}"""

src = src.replace(old, new)
with open(path, "w") as f:
    f.write(src)
print("updated")
EOF
