//! Tree rendering used by the `list` command.

use std::fs;
use std::path::Path;

use crate::error::AppError;

const BLUE: &str = "\x1b[0;34m";
const RESET: &str = "\x1b[0m";

#[derive(Copy, Clone, Debug)]
pub enum Mode {
    All,
    Notes,
    Folders,
}

pub fn render(root: &Path, title: &str, mode: Mode) -> Result<String, AppError> {
    let mut out = String::new();
    out.push_str(title);
    out.push('\n');
    render_dir(root, &mut out, "", mode, true)?;
    Ok(out)
}

fn display_name(name: &str, is_dir: bool) -> String {
    let p = Path::new(name);
    if is_dir {
        // Folders: strip last extension (e.g. "has.dot" -> "has").
        p.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_else(|| name.to_string())
    } else {
        // Notes: strip ".md"; otherwise keep as-is (e.g. "foo" -> "foo",
        // "foo.md" -> "foo", "foo.txt" not shown at all).
        if p.extension().map(|e| e == "md").unwrap_or(false) {
            p.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_else(|| name.to_string())
        } else {
            name.to_string()
        }
    }
}

fn collect(root: &Path, mode: Mode, top_level: bool) -> Result<Vec<std::fs::DirEntry>, AppError> {
    let iter = fs::read_dir(root).map_err(|e| AppError::new(format!(
        "no such file or directory (os error {})", e.raw_os_error().unwrap_or(2))))?;
    let mut entries: Vec<_> = iter.filter_map(|r| r.ok()).collect();
    entries.retain(|e| {
        let path = e.path();
        let name = e.file_name().to_string_lossy().into_owned();
        match mode {
            Mode::Notes => {
                if path.is_dir() { return false; }
                path.extension().map(|e| e == "md").unwrap_or(false)
            }
            Mode::Folders => path.is_dir(),
            Mode::All => {
                if path.is_dir() {
                    if top_level && name == ".jot" { return false; }
                    true
                } else {
                    match path.extension() {
                        Some(ext) => ext == "md",
                        None => true,
                    }
                }
            }
        }
    });
    Ok(entries)
}

fn render_dir(dir: &Path, out: &mut String, prefix: &str, mode: Mode, top_level: bool)
    -> Result<(), AppError>
{
    let entries = collect(dir, mode, top_level)?;
    let n = entries.len();
    for (idx, entry) in entries.iter().enumerate() {
        let is_last = idx + 1 == n;
        let branch = if is_last { "└── " } else { "├── " };
        let file_name = entry.file_name().to_string_lossy().into_owned();
        let path = entry.path();
        if path.is_dir() {
            let display = display_name(&file_name, true);
            out.push_str(prefix);
            out.push_str(branch);
            out.push_str(&display);
            out.push('\n');
            if matches!(mode, Mode::All) {
                let new_prefix = format!("{}{}", prefix, if is_last { "    " } else { "│   " });
                render_dir(&path, out, &new_prefix, Mode::All, false)?;
            }
        } else {
            let display = display_name(&file_name, false);
            out.push_str(prefix);
            out.push_str(branch);
            out.push_str(BLUE);
            out.push_str(&display);
            out.push_str(RESET);
            out.push('\n');
        }
    }
    Ok(())
}
