use std::path::Path;
use std::process::Command;

use crate::error::AppError;
use crate::fsutil::note_path;
use crate::state::{Config, Vaults, VaultData};

pub fn run(name: &str) -> Result<(), AppError> {
    let vaults = Vaults::load();
    let current = vaults.current().ok_or_else(|| AppError::new("not inside a vault"))?;
    let location = vaults.location_of(&current).ok_or_else(|| AppError::new("not inside a vault"))?;
    let data = VaultData::load(&location, &current)?;
    let cur_dir = data.current_path();
    let path = note_path(&cur_dir, name);
    if !path.exists() || path.is_dir() {
        return Err(AppError::new(format!("note {} not found", name)));
    }
    let cfg = Config::load();
    let editor = cfg.editor();
    if editor.is_empty() {
        return Err(AppError::new("editor not found"));
    }
    run_editor(&editor, &path)
}

pub(crate) fn run_editor(editor: &str, target: &Path) -> Result<(), AppError> {
    let parts: Vec<&str> = editor.split_whitespace().collect();
    if parts.is_empty() {
        return Err(AppError::new("editor not found"));
    }
    let status = Command::new(parts[0])
        .args(&parts[1..])
        .arg(target)
        .status();
    match status {
        Ok(_) => Ok(()),
        Err(_) => Err(AppError::new("editor not found")),
    }
}
