use std::fs;

use crate::cli::ItemKind;
use crate::error::{AppError, BLUE, RESET};
use crate::fsutil::note_path;
use crate::state::{Vaults, VaultData};

pub fn run(kind: ItemKind, name: &str) -> Result<(), AppError> {
    match kind {
        ItemKind::Vault => remove_vault(name),
        ItemKind::Note => remove_note(name),
        ItemKind::Folder => remove_folder(name),
    }
}

fn remove_vault(name: &str) -> Result<(), AppError> {
    let mut vaults = Vaults::load();
    let location = match vaults.location_of(name) {
        Some(l) => l,
        None => return Err(AppError::new(format!("vault {} doesn't exist", name))),
    };
    let dir = std::path::Path::new(&location).join(name);
    if dir.exists() {
        fs::remove_dir_all(&dir).map_err(|e| AppError::new(format!("io error: {}", e)))?;
    }
    vaults.remove(name);
    if vaults.current().as_deref() == Some(name) {
        vaults.set_current(None);
    }
    vaults.save();
    println!("vault {}{}{} removed", BLUE, name, RESET);
    Ok(())
}

fn require_current() -> Result<(Vaults, String, String), AppError> {
    let vaults = Vaults::load();
    let current = vaults.current().ok_or_else(|| AppError::new("not inside a vault"))?;
    let location = vaults.location_of(&current).ok_or_else(|| AppError::new("not inside a vault"))?;
    Ok((vaults, current, location))
}

fn remove_note(name: &str) -> Result<(), AppError> {
    let (_vaults, current, location) = require_current()?;
    let data = VaultData::load(&location, &current)?;
    let cur_dir = data.current_path();
    let path = note_path(&cur_dir, name);
    if !path.exists() || path.is_dir() {
        return Err(AppError::new(format!("note {} not found", name)));
    }
    fs::remove_file(&path).map_err(|e| AppError::new(format!("io error: {}", e)))?;
    println!("note {}{}{} removed", BLUE, name, RESET);
    Ok(())
}

fn remove_folder(name: &str) -> Result<(), AppError> {
    let (_vaults, current, location) = require_current()?;
    let data = VaultData::load(&location, &current)?;
    let path = data.current_path().join(name);
    if !path.exists() || !path.is_dir() {
        return Err(AppError::new(format!("folder {} not found", name)));
    }
    fs::remove_dir_all(&path).map_err(|e| AppError::new(format!("io error: {}", e)))?;
    println!("folder {}{}{} removed", BLUE, name, RESET);
    Ok(())
}
