use std::path::{Component, Path, PathBuf};

use crate::error::AppError;
use crate::state::{Vaults, VaultData};

pub fn run(path: &str) -> Result<(), AppError> {
    let vaults = Vaults::load();
    let current = vaults.current().ok_or_else(|| AppError::new("not inside a vault"))?;
    let location = vaults.location_of(&current).ok_or_else(|| AppError::new("not inside a vault"))?;
    let mut data = VaultData::load(&location, &current)?;

    // Reject absolute input outright.
    if Path::new(path).is_absolute() {
        return Err(AppError::new("couldn't find the path specified"));
    }

    // Combine vault-root + current-folder + input.
    let probe = data.current_path().join(path);

    // Canonicalise against the filesystem so that any intermediate
    // component that isn't a directory (including "..") fails.
    let canonical = std::fs::canonicalize(&probe)
        .map_err(|_| AppError::new("couldn't find the path specified"))?;

    // Determine the canonical vault root for range checks.
    let root = std::fs::canonicalize(data.vault_root())
        .map_err(|_| AppError::new("couldn't find the path specified"))?;

    // Must remain strictly within the vault.
    let rel = match canonical.strip_prefix(&root) {
        Ok(p) => p.to_path_buf(),
        Err(_) => return Err(AppError::new("path crosses the bounds of vault")),
    };

    let new_folder = relpath_to_string(&rel);
    if new_folder == data.folder {
        return Err(AppError::new("new location is same as old location"));
    }
    data.folder = new_folder;
    data.save().map_err(|e| AppError::new(format!("io error: {}", e)))?;
    println!("folder changed");
    Ok(())
}

fn relpath_to_string(p: &Path) -> String {
    let mut parts = Vec::new();
    for c in p.components() {
        if let Component::Normal(s) = c {
            parts.push(s.to_string_lossy().into_owned());
        }
    }
    parts.join("/")
}
EOF

